import os
from typing import List, Dict, Any, Optional

from openai import OpenAI


class ContentSafetyModerator:
    def __init__(self, api_key: Optional[str] = None, model: str = "omni-moderation-latest"):
        self.client = OpenAI(api_key=api_key or os.getenv("OPENAI_API_KEY"))
        self.model = model

    def moderate_batch(self, messages: List[str]) -> List[Dict[str, Any]]:
        results: List[Dict[str, Any]] = []

        for message in messages:
            resp = self.client.moderations.create(
                model=self.model,
                input=message,
            )

            result = resp.results[0]
            categories = dict(result.categories)
            scores = dict(result.category_scores)

            flagged = bool(result.flagged)
            decision = "block" if flagged else "allow"

            results.append(
                {
                    "message": message,
                    "decision": decision,
                    "flagged": flagged,
                    "categories": categories,
                    "category_scores": scores,
                }
            )

        return results


def moderate_messages(messages: List[str], api_key: Optional[str] = None) -> List[Dict[str, Any]]:
    return ContentSafetyModerator(api_key=api_key).moderate_batch(messages)
